const numbers = [1, 2, 3];
numbers[10] = 11;
let calls = 0;
const mapped = numbers.map(n => { calls++; return n * 2; });
const result = [numbers.length, Object.hasOwn(numbers, 3), calls, mapped[10]];
// [11, false, 4, 22]

